import React, { useState } from 'react';
import {
  FileCode,
  Sparkles,
  Settings,
  ChevronDown,
  Layers,
  LayoutGrid,
} from 'lucide-react';
import { ModFolderInfo } from '../types/wormforge';

/**
 * Packs deliberately NOT offered by the "Load Mod / Script" menu.
 *
 * These are example mods that are also loaded by the mod loader, so offering
 * them here as well is redundant. Ids are the corpus ids in
 * `src/data/existingMods.ts` (generated by `scripts/__gen_corpus.ts`).
 */
const EXCLUDED_FROM_LOADER: readonly string[] = [
  'example.gifdonkeylua',    // GIF Donkey
  'example.wormtoss',        // Worm Toss
  'example.wormstatelogger', // Worm State Logger
  'example.hellishgrenade',  // Hellish Grenade
  'example.mineemit',        // Mine Emit
  'example.qbazooka',        // Q Bazooka
  'example.turret',          // Turret
  'example.wormcraft',       // Wormcraft
  'example.panelicon',       // Panel Icon
  'example.hurtlab',         // Hurt Lab
  'example.gravlerstrike',   // Gravler Strike
];

interface StudioHeaderProps {
  activeFile: string;
  onSelectFile: (file: string) => void;
  openFiles: string[];
  onCloseFile: (file: string) => void;
  onLoadTemplate: (templateId: string) => void;
  onOpenConfig: () => void;
  // The real corpus, so the "Load Mod / Script" menu can only ever offer ids
  // that actually resolve. Optional: with no data it renders an empty state.
  existingMods?: ModFolderInfo[];
  // Shown only when a mods root is configured. Lets the user get back to the
  // mods grid from the editor without opening Config.
  onOpenModsList?: () => void;
  isLight?: boolean;
}

export const StudioHeader: React.FC<StudioHeaderProps> = ({
  activeFile,
  onSelectFile,
  openFiles,
  onCloseFile,
  onLoadTemplate,
  onOpenConfig,
  existingMods,
  onOpenModsList,
  isLight = false,
}) => {
  const [isTemplatesOpen, setIsTemplatesOpen] = useState(false);

  // The menu is built from the real corpus instead of two hand-written id
  // arrays. Those arrays named `example.bee`, `example.saw`,
  // `gameplay.highlander_full`, `example.worm_toss`, ... -- ids that do NOT exist
  // in EXISTING_MODS -- so `onLoadTemplate(id)` found nothing and EVERY entry
  // silently did nothing. Reading the ids off the data makes that impossible.
  const excluded = new Set(EXCLUDED_FROM_LOADER);
  const loadable = (existingMods ?? []).filter((m) => !excluded.has(m.id));
  const isWeaponish = (m: ModFolderInfo) => m.category === 'weapons' || m.category === 'weapon';
  const isRuleish = (m: ModFolderInfo) => m.category === 'rules' || m.category === 'gameplay';
  const loaderSections: { label: string; accent: boolean; mods: ModFolderInfo[] }[] = [
    { label: '★ Rules & Gameplay Packs', accent: true, mods: loadable.filter(isRuleish) },
    { label: 'Weapons & Actor Mods', accent: false, mods: loadable.filter(isWeaponish) },
    {
      label: 'Examples & Utilities',
      accent: false,
      mods: loadable.filter((m) => !isRuleish(m) && !isWeaponish(m)),
    },
  ];
  const visibleSections = loaderSections.filter((s) => s.mods.length > 0);

  return (
    <header
      className={`border-b text-xs select-none transition-colors ${
        isLight
          ? 'bg-slate-100 border-slate-300 text-slate-800'
          : 'bg-[#14171c] border-[#262c35] text-[#cfdbe8]'
      }`}
    >
      {/* Top Main Bar */}
      <div className="px-3 py-2 flex items-center justify-between gap-3">
        {/* Brand Zone */}
        <div className="flex items-center gap-2.5">
          <div className="w-6 h-6 rounded bg-gradient-to-br from-amber-400 to-amber-600 flex items-center justify-center text-slate-950 font-bold shadow-md">
            W
          </div>
          <div>
            <h1 className="font-bold text-[13px] tracking-tight flex items-center gap-1.5">
              <span className={isLight ? 'text-slate-900 font-extrabold' : 'text-[#e4edf7]'}>
                WormForge Code Studio
              </span>
              <span className="text-[10px] px-1.5 py-0.2 rounded bg-amber-500/20 text-amber-500 font-mono border border-amber-500/30">
                v0.8.22 dev
              </span>
            </h1>
          </div>
        </div>

        {/* Center: Active Document Status Indicator */}
        <div className="hidden md:flex items-center gap-2">
          <div
            className={`flex items-center gap-1.5 px-3 py-1 rounded-full border text-[11px] font-mono ${
              isLight
                ? 'bg-white border-slate-200 text-slate-600'
                : 'bg-[#1b2028] border-[#2a3340] text-[#899cb2]'
            }`}
          >
            <span className="w-2 h-2 rounded-full bg-emerald-500 inline-block" />
            <span className="opacity-75">Active Mod File:</span>
            <span className="font-semibold text-amber-500">{activeFile}</span>
          </div>
        </div>

        {/* Right Actions */}
        <div className="flex items-center gap-2">
          {/* Quick Preset Selector */}
          <div className="relative">
            <button
              onClick={() => setIsTemplatesOpen(!isTemplatesOpen)}
              className={`flex items-center gap-1.5 px-2.5 py-1 rounded border font-medium transition-colors shadow-xs ${
                isLight
                  ? 'bg-white hover:bg-slate-50 text-slate-700 border-slate-300'
                  : 'bg-[#20252e] hover:bg-[#2a313d] text-[#c9d7e6] border-[#2e3745]'
              }`}
            >
              <Sparkles className="w-3.5 h-3.5 text-amber-500" />
              <span>Load Mod / Script</span>
              <ChevronDown className="w-3 h-3 text-[#708094]" />
            </button>

            {isTemplatesOpen && (
              <div
                className={`absolute right-0 mt-1 w-68 rounded-md shadow-2xl py-1 z-50 text-xs max-h-96 overflow-y-auto border divide-y ${
                  isLight
                    ? 'bg-white border-slate-300 text-slate-800 divide-slate-100'
                    : 'bg-[#1a1e26] border-[#313a48] text-[#d4e0ed] divide-[#222834]'
                }`}
              >
                {visibleSections.length === 0 ? (
                  <div
                    className={`px-2.5 py-3 text-[11px] text-center ${
                      isLight ? 'text-slate-500' : 'text-[#637488]'
                    }`}
                  >
                    No loadable packs available.
                  </div>
                ) : (
                  visibleSections.map((section) => (
                    <div key={section.label}>
                      <div
                        className={`px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${
                          section.accent
                            ? isLight
                              ? 'bg-amber-50 text-amber-800'
                              : 'bg-[#212631] text-amber-400'
                            : isLight
                              ? 'bg-slate-50 text-slate-500'
                              : 'bg-[#14171d] text-[#637488]'
                        }`}
                      >
                        {section.label}
                      </div>
                      {section.mods.map((m) => (
                        <button
                          key={m.id}
                          onClick={() => {
                            onLoadTemplate(m.id);
                            setIsTemplatesOpen(false);
                          }}
                          title={m.id}
                          className={`w-full text-left px-2.5 py-1.5 flex items-center justify-between transition-colors ${
                            isLight
                              ? 'hover:bg-slate-100 text-slate-700 hover:text-slate-900'
                              : 'hover:bg-[#242b36] text-[#bccadb] hover:text-white'
                          }`}
                        >
                          <span className="truncate">{m.name}</span>
                          {m.category && (
                            <span className="ml-1 shrink-0 text-[9px] font-mono px-1 py-0.2 rounded bg-amber-500/20 text-amber-600">
                              {m.category}
                            </span>
                          )}
                        </button>
                      ))}
                    </div>
                  ))
                )}
              </div>
            )}
          </div>

          {/* Mods Grid Button - only when a mods root is configured, so it never
              appears for users who have not opted into the feature. */}
          {onOpenModsList && (
            <button
              onClick={onOpenModsList}
              title="Back to mods list"
              className={`flex items-center gap-1.5 px-2.5 py-1 rounded font-medium border transition-colors shadow-xs ${
                isLight
                  ? 'bg-white hover:bg-slate-50 text-slate-700 border-slate-300'
                  : 'bg-[#20252e] hover:bg-[#2a313d] text-[#c9d7e6] border-[#2e3745]'
              }`}
            >
              <LayoutGrid className="w-3.5 h-3.5 text-amber-500" />
              <span>Mods</span>
            </button>
          )}

          {/* Config / Settings Button */}
          <button
            onClick={onOpenConfig}
            title="Open Editor Settings (Font size, Spacing, Light Mode, Startup Folder)"
            className={`flex items-center gap-1.5 px-2.5 py-1 rounded font-medium border transition-colors shadow-xs ${
              isLight
                ? 'bg-white hover:bg-slate-50 text-slate-700 border-slate-300'
                : 'bg-[#20252e] hover:bg-[#2a313d] text-[#c9d7e6] border-[#2e3745]'
            }`}
          >
            <Settings className="w-3.5 h-3.5 text-amber-500" />
            <span>Config</span>
          </button>
        </div>
      </div>

      {/* Editor Tabs Bar */}
      <div
        className={`px-2 flex items-center gap-1 overflow-x-auto border-t ${
          isLight ? 'bg-slate-200 border-slate-300' : 'bg-[#101317] border-[#1e232c]'
        }`}
      >
        {openFiles.map((file) => (
          <div
            key={file}
            onClick={() => onSelectFile(file)}
            className={`group flex items-center gap-1.5 px-3 py-1.5 border-r cursor-pointer text-xs font-mono transition-colors ${
              activeFile === file
                ? isLight
                  ? 'bg-white text-amber-700 font-bold border-t-2 border-t-amber-500 border-r-slate-300 shadow-xs'
                  : 'bg-[#111418] text-amber-300 font-semibold border-t-2 border-t-amber-400 border-r-[#1e232c]'
                : isLight
                ? 'text-slate-600 hover:text-slate-900 hover:bg-slate-100 border-r-slate-300'
                : 'text-[#6c7d92] hover:text-[#a9bacd] hover:bg-[#15191f] border-r-[#1e232c]'
            }`}
          >
            <FileCode className="w-3.5 h-3.5 opacity-80" />
            <span>{file}</span>
            {openFiles.length > 1 && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onCloseFile(file);
                }}
                className="opacity-0 group-hover:opacity-100 hover:text-rose-500 p-0.5 ml-1 transition-opacity"
              >
                &times;
              </button>
            )}
          </div>
        ))}
      </div>
    </header>
  );
};
